import{_ as a,o,c as r,a2 as i}from"./chunks/framework.BNuav-ne.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792557099000}'),t={name:"guide/faq.md"};function l(d,e,n,h,c,s){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="保存配置后没有变化" tabindex="-1">保存配置后没有变化 <a class="header-anchor" href="#保存配置后没有变化" aria-label="Permalink to &quot;保存配置后没有变化&quot;">​</a></h2><ol><li>确认已开通 JS 权限，博客皮肤为 <code>SimpleMemory</code>，并勾选「禁用模板默认 CSS」。</li><li>核对 CSS 与脚本版本；页面只引入一次插件。</li><li><code>window.cnblogsConfig</code> 放在插件脚本之前。添加配置时合并字段，不要在后面重新赋值覆盖原配置。</li><li>打开浏览器控制台，检查语法错误；在 Network 面板检查脚本和资源请求。</li></ol><p>安装位置和完整示例见<a href="./install.html">安装配置</a>。</p><h2 id="页面一直-loading-或者部分内容没有样式" tabindex="-1">页面一直 Loading，或者部分内容没有样式 <a class="header-anchor" href="#页面一直-loading-或者部分内容没有样式" aria-label="Permalink to &quot;页面一直 Loading，或者部分内容没有样式&quot;">​</a></h2><p>先检查插件入口、脚本分包和 CSS 是否加载成功。自托管时必须上传整个 <code>dist/</code> 目录，不能只上传入口脚本。也要检查配置中的图片和外部脚本是否可以通过 HTTPS 访问。</p><p>可以临时<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/loading.html#隐藏遮罩">隐藏 Loading 遮罩</a>查看页面，但隐藏遮罩不会修复加载错误。</p><h2 id="侧边栏没有分类、标签或排行" tabindex="-1">侧边栏没有分类、标签或排行 <a class="header-anchor" href="#侧边栏没有分类、标签或排行" aria-label="Permalink to &quot;侧边栏没有分类、标签或排行&quot;">​</a></h2><p>先在博客园后台开启对应控件，再确认栏目确实有数据。设置可能有缓存，稍等后刷新。更多排查见<a href="./menuData.html">侧边栏数据</a>。</p><h2 id="文章目录没有显示" tabindex="-1">文章目录没有显示 <a class="header-anchor" href="#文章目录没有显示" aria-label="Permalink to &quot;文章目录没有显示&quot;">​</a></h2><p>正文需要有真正的 <code>h1</code>～<code>h6</code> 标题；只加粗文字不会生成目录。窄屏或两侧空间不足时目录会自动隐藏，可以尝试右下角目录按钮。相关配置见<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/config/article.html#articledirectory-文章目录">文章配置</a>。</p><h2 id="代码出现双行号或高亮不对" tabindex="-1">代码出现双行号或高亮不对 <a class="header-anchor" href="#代码出现双行号或高亮不对" aria-label="Permalink to &quot;代码出现双行号或高亮不对&quot;">​</a></h2><p>不要同时开启博客园与插件的行号。先按<a href="./install.html#代码高亮">安装教程</a>核对后台设置，再检查<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/config/code.html">代码配置</a>。</p><h2 id="修改日夜模式配置后没有变化" tabindex="-1">修改日夜模式配置后没有变化 <a class="header-anchor" href="#修改日夜模式配置后没有变化" aria-label="Permalink to &quot;修改日夜模式配置后没有变化&quot;">​</a></h2><p>手动切换的模式会保存在 Cookie 中，优先于自动时段选择。可以点击切换按钮或清除站点的 <code>cnblogs_config_isNight</code> Cookie 后重试。<code>nightMode: true</code> 会覆盖初始化时的模式选择；<code>enable: false</code> 则关闭整个切换功能。</p><h2 id="书单或友链不显示" tabindex="-1">书单或友链不显示 <a class="header-anchor" href="#书单或友链不显示" aria-label="Permalink to &quot;书单或友链不显示&quot;">​</a></h2><p>确认文章正文包含对应的隐藏标记，并将数据写在全局配置中。友链需要按分类提供 <code>links</code> 数组，不能直接将好友对象放入 <code>links.page</code>。参见<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/bookList.html">书单页</a>和<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/links.html">友链页</a>。</p><h2 id="仍然无法解决" tabindex="-1">仍然无法解决 <a class="header-anchor" href="#仍然无法解决" aria-label="Permalink to &quot;仍然无法解决&quot;">​</a></h2><p>请在 <a href="https://github.com/BNDong/Cnblogs-Theme-SimpleMemory/issues" target="_blank" rel="noreferrer">Issues</a> 附上博客链接、插件版本、浏览器、复现步骤，以及控制台报错或截图。贴配置前去掉不需要公开的信息。</p>',19)])])}const p=a(t,[["render",l]]);export{f as __pageData,p as default};
